"""Demo: verify the standard basis realises the equidistant metric at sqrt(2)."""
from __future__ import annotations
import itertools, math
from typing import List, Tuple

def standard_basis(n: int) -> List[Tuple[float, ...]]:
    return [tuple(1.0 if i == k else 0.0 for i in range(n)) for k in range(n)]

def euclidean_distance(u: Tuple[float, ...], v: Tuple[float, ...]) -> float:
    return math.sqrt(sum((a - b) ** 2 for a, b in zip(u, v)))

def all_pairwise_distances(n: int) -> List[float]:
    basis = standard_basis(n)
    return [euclidean_distance(basis[i], basis[j])
            for i, j in itertools.combinations(range(n), 2)]

if __name__ == "__main__":
    for n in range(2, 8):
        dists = all_pairwise_distances(n)
        print(f"n={n}: distinct pairwise distances = {sorted(set(round(d, 12) for d in dists))}"
              f"  (sqrt2 = {math.sqrt(2):.12f})")

"""Demo: the single exponential cliff of the equidistant VR complex."""
from __future__ import annotations
import itertools, math
from typing import Tuple

def equi(i: int, j: int, d: float) -> float:
    return 0.0 if i == j else d

def vr_size(n: int, d: float, r: float) -> int:
    count = 0
    for k in range(n + 1):
        for S in itertools.combinations(range(n), k):
            if all(equi(i, j, d) <= r for i, j in itertools.combinations(S, 2)):
                count += 1
    return count

if __name__ == "__main__":
    d = math.sqrt(2.0)
    print(f"{'n':>3} {'below (r<d)':>12} {'n+1':>6} {'at/above (r>=d)':>16} {'2^n':>8}")
    for n in range(1, 9):
        print(f"{n:>3} {vr_size(n, d, d-0.1):>12} {n+1:>6} "
              f"{vr_size(n, d, d):>16} {2**n:>8}")

"""Demo: the threshold exponent gamma(c) = 1/2 - log2(c) and the headline floor."""
from __future__ import annotations
import math

def gamma(c: float) -> float:
    return 0.5 - math.log2(c)

def headline_floor(c: float, n: int) -> float:
    return 2.0 ** (gamma(c) * n)

if __name__ == "__main__":
    sqrt2 = math.sqrt(2.0)
    print("Threshold exponent gamma(c):")
    for c in [1.0, 1.1, 1.2, 1.3, 1.4, 1.414, sqrt2]:
        print(f"  c={c:.4f}  gamma={gamma(c):+.6f}  positive={gamma(c) > 1e-12}")
    print("\nHeadline floor 2^(gamma(c)*n):")
    for c in [1.0, 1.2, 1.4]:
        for n in [10, 50, 100]:
            print(f"  c={c:.2f} n={n:>3}: 2^(gamma*n) = {headline_floor(c, n):.4e}")

"""Demo: an explicit c-interleaving witness forced to contain the full power set."""
from __future__ import annotations
import itertools, math
from typing import List, Tuple

def equi(i: int, j: int, d: float) -> float:
    return 0.0 if i == j else d

def vr_complex(n: int, d: float, r: float) -> List[Tuple[int, ...]]:
    out: List[Tuple[int, ...]] = []
    for k in range(n + 1):
        for S in itertools.combinations(range(n), k):
            if all(equi(i, j, d) <= r for i, j in itertools.combinations(S, 2)):
                out.append(S)
    return out

def forced_lower_bound(n: int, c: float, d: float) -> Tuple[int, int]:
    """Return (|VR(d)|, forced min |G(c*d)|) -- they coincide and equal 2^n."""
    vr_at_gap = vr_complex(n, d, d)   # full power set at the gap
    return len(vr_at_gap), len(vr_at_gap)

if __name__ == "__main__":
    d = math.sqrt(2.0)
    for n in range(1, 9):
        for c in [1.0, 1.25, 1.41]:
            vr, forced = forced_lower_bound(n, c, d)
            assert forced == 2 ** n
            print(f"n={n} c={c:.2f}: VR(d) has {vr} simplices  =>  |G(c*d)| >= {forced} = 2^{n}")

