function VIETORIS_RIPS(n, D, r):
    simplices <- empty list
    for k from 0 to n:
        for each subset S of {0,...,n-1} with |S| = k:
            ok <- true
            for each unordered pair {i,j} in S:
                if D(i,j) > r: ok <- false; break
            if ok: append S to simplices
    return simplices

function EQUIDISTANT_VR_SIZE(n, d, r):
    if r < d: return n + 1          # empty set + n vertices
    else:      return 2^n           # full power set (requires d >= 0)

function BARCODE_CLIFF(n, d):
    below <- EQUIDISTANT_VR_SIZE(n, d, d - epsilon)
    above <- EQUIDISTANT_VR_SIZE(n, d, d)
    return (below, above, above - below)

function GUARANTEED_LOWER_BOUND(n, c):
    require 1 <= c < sqrt(2)
    g <- 1/2 - log2(c)              # gamma(c) > 0 on [1, sqrt2)
    floor <- 2^(g * n)              # headline lower bound
    uniform <- 2^n                  # stronger uniform bound
    return (floor, uniform)
